const{Vec3}=require('vec3');bot.clearControlStates();bot.pathfinder.setGoal(null);let c,bank;try{c=await bot.openChest(bot.blockAt(new Vec3(7,67,82)));bank=c.containerItems().map(i=>[i.name,i.count,i.durabilityUsed]);}finally{if(c)c.close()}return{p:bot.entity.position,hp:bot.health,inv:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed]),bank,cells:[[6,67,84],[7,67,84],[6,68,84],[7,68,84],[6,69,84],[7,69,84],[5,69,82],[5,68,82],[5,69,83],[5,68,83],[5,69,84],[5,68,84]].map(a=>{let p=new Vec3(...a),b=bot.blockAt(p);return[a,b?.name,bot.blockAt(p.offset(0,-1,0))?.name]})};
